with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '快楽の園', 'ヒエロニムス・ボス', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/The_Garden_of_Earthly_Delights_by_Bosch_High_Resolution_2.jpg/960px-The_Garden_of_Earthly_Delights_by_Bosch_High_Resolution_2.jpg', '15世紀末から16世紀初めごろ、ネーデルラントの画家ヒエロニムス・ボスが描いた三連祭壇画で、マドリードのプラド美術館が所蔵しています。左の翼にはエデンの園、中央には裸の人々が巨大な果実や鳥とたわむれる不思議な楽園、右の翼には楽器や怪物が入り乱れる地獄が描かれています。扉を閉じると、天地創造のころの地球が灰色の濃淡で現れます。細部の奇妙な生き物を探しながら、左から右へ物語をたどってみてください。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:The_Garden_of_Earthly_Delights_by_Bosch_High_Resolution_2.jpg'),
    (2, '秋冬山水図', '雪舟', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/SesshuToyo.jpg/960px-SesshuToyo.jpg', '室町時代の画僧・雪舟が描いた2幅の水墨山水画で、東京国立博物館が所蔵する国宝です。雪舟は中国・明に渡って本場の水墨画を学び、帰国後に力強い独自の画風を築きました。冬景図では、雪に覆われた険しい山の中央を、上から下へ鋭い一本の線が走ります。この線が画面を引き締め、冬の冷たい空気まで伝えています。筆の強弱と、塗り残した紙の白さに注目すると、墨だけで季節を描き分ける工夫が見えてきます。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:SesshuToyo.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

