values ('サーカスのレスラー', 'Wrestlers in a Circus', 'エルンスト・ルートヴィヒ・キルヒナー', 'Ernst Ludwig Kirchner',
        1909,
        (select slug from public.art_movements where slug = 'expressionism'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1966.49/1966.49_web.jpg', '1909年、ドレスデンで画家グループ「ブリュッケ（橋）」の一員として活動していたキルヒナーが描いた油彩画です。色鮮やかなマットの上で、たくましいレスラーたちが組み合っています。ゆるやかで荒い筆づかいが、激しく動く体のぶれをとらえ、観客の熱気まで想像させます。目に見えるとおりに写すより、強い色と形で感情や動きを伝えようとしたドイツ表現主義の特徴がよく表れており、のちのベルリンの街路を描いた作品へとつながっていきます。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1966.49')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

