insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('エルンスト・ルートヴィヒ・キルヒナー', 'Ernst Ludwig Kirchner', 'キルヒナー',
        1880, 1938, 'west', array['expressionism']::text[],
        '画家グループ「ブリュッケ」を結成した、ドイツ表現主義を代表する画家。', 'ドイツの画家で、ドイツ表現主義を代表する一人です。1905年、ドレスデンでヘッケルやシュミット＝ロットルフらと画家グループ「ブリュッケ」（「橋」の意）を結成しました。ブリュッケは共通の様式を持つ集団ではなく、従来のアカデミックな芸術に反抗する若い画家たちの集まりでした。

強い色彩と荒々しい形で、サーカスや裸婦、都市の人々を描きました。グループが1913年に解散したころには、ベルリンの街を題材にした大作を数多く発表しています。

第一次世界大戦で兵役に就いたのちに心身を病み、療養のためスイスのダヴォスに移って山の風景を描き続けました。ナチスの「退廃芸術」展には多くの作品が展示されました。ダヴォスには彼の作品を多く所蔵するキルヒナー美術館があります。', 'https://ja.wikipedia.org/wiki/%E3%82%A8%E3%83%AB%E3%83%B3%E3%82%B9%E3%83%88%E3%83%BB%E3%83%AB%E3%83%BC%E3%83%88%E3%83%B4%E3%82%A3%E3%83%92%E3%83%BB%E3%82%AD%E3%83%AB%E3%83%92%E3%83%8A%E3%83%BC')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ヒエロニムス・ボス', 'Hieronymus Bosch', 'ボス',
        null, 1516, 'west', array['renaissance']::text[],
        '奇妙な生き物や幻想的な情景を描いた、ネーデルラントの画家。', 'ネーデルラントの画家で、1450年ごろ、スヘルトーヘンボス（デン・ボス）の画家一族に生まれました。父や祖父、兄も画家で、父の工房で技術を身につけたと考えられていますが、生前の記録が少なく、生涯には分からないことが多く残っています。

キリスト教の教えを主題に、人間の欲望や罪、天国と地獄を、半分人間で半分動物のような奇妙な生き物や、現実にはありえない情景で描きました。細部まで描き込まれた画面は、見る人を長く引きつけます。

代表作に、三連祭壇画の《快楽の園》《聖アントニウスの誘惑》《最後の審判》があります。その想像力は、のちのピーテル・ブリューゲル（父）や、20世紀のシュルレアリスムの画家たちにも受け継がれました。', 'https://ja.wikipedia.org/wiki/%E3%83%92%E3%82%A8%E3%83%AD%E3%83%8B%E3%83%A0%E3%82%B9%E3%83%BB%E3%83%9C%E3%82%B9')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
